<?php $pageTitle='Programmes';$verified=count(array_filter($programmes,static fn($p)=>$p['status']==='verified'));$undergraduate=count(array_filter($programmes,static fn($p)=>$p['level']==='undergraduate')); ?>
<div class="gov-page gov-enter"><section class="gov-hero"><div><div class="gov-brand"><img src="<?= e(url('assets/images/gbu-emblem.png')) ?>" alt="" width="44" height="44"><span>Gautam Buddha University<br><b>Academic master data</b></span></div><h1>Programme directory</h1><p>Control roll-number codes and programme mappings used for student parsing, eligibility, and examination reporting.</p></div><div class="gov-hero-stat"><span class="gov-icon icon-programme" aria-hidden="true"></span><strong><?= count($programmes) ?></strong><small>programme mappings</small></div></section><?php if($success):?><div class="alert success" role="status"><?= e($success) ?></div><?php endif;?><?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?><section class="gov-metrics"><div><span>Total mappings</span><strong><?= count($programmes) ?></strong><small>Across all schools</small></div><div><span>Verified codes</span><strong><?= $verified ?></strong><small>Approved for parsing</small></div><div><span>Undergraduate</span><strong><?= $undergraduate ?></strong><small>Programme mappings</small></div></section>
<div class="master-workspace programme-workspace"><form class="master-create" method="post" action="<?= e(url('masters/programmes')) ?>"><?= csrf_field() ?><header><span class="gov-icon icon-add" aria-hidden="true"></span><div><h2>Add programme mapping</h2><p>Register an official roll-number code.</p></div></header><label>Owning school<select name="school_id" required><option value="">Select university school</option><?php foreach($schools as $school):?><option value="<?= (int)$school['id'] ?>"><?= e($school['code'].' - '.$school['name']) ?></option><?php endforeach;?></select></label><div class="master-field-pair"><label>Roll-number code<input name="code" placeholder="Example: UCS" required></label><label>Duration<input type="number" name="duration_semesters" min="1" max="20" placeholder="8"><small>Semesters</small></label></div><label>Programme name<input name="name" placeholder="Bachelor of Technology in Computer Science" required></label><label>Academic level<select name="level"><option value="undergraduate">Undergraduate</option><option value="postgraduate">Postgraduate</option><option value="integrated">Integrated</option><option value="doctoral">Doctoral</option><option value="diploma">Diploma</option><option value="other">Other</option></select></label><div class="master-checks"><label><input type="checkbox" name="lateral_entry" value="1"><span>Lateral entry code</span></label><label><input type="checkbox" name="legacy" value="1"><span>Legacy code</span></label></div><button <?= !$schools?'disabled':'' ?>><span>Create mapping</span><b aria-hidden="true">→</b></button></form><section class="master-register"><header><div><h2>Programme mappings</h2><p>Verified codes drive automatic roll-number parsing.</p></div><label class="gov-search"><span class="gov-icon icon-search" aria-hidden="true"></span><input data-gov-search type="search" placeholder="Search code, programme, or school" aria-label="Search programmes"></label></header><?php if($programmes):?><div class="programme-list" data-gov-list><?php foreach($programmes as $i=>$programme):?><article data-gov-row data-search="<?= e(strtolower($programme['code'].' '.$programme['name'].' '.$programme['school_name'].' '.$programme['level'])) ?>" style="--gov-order:<?= $i ?>"><div class="programme-code"><span><?= e($programme['code']) ?></span><small><?= $programme['lateral_entry']?'Lateral':($programme['legacy']?'Legacy':'Regular') ?></small></div><div><h3><?= e($programme['name']) ?></h3><p><?= e($programme['school_short_name']?:$programme['school_name']) ?></p></div><div class="programme-level"><strong><?= e(ucfirst($programme['level'])) ?></strong><span><?= $programme['duration_semesters']?(int)$programme['duration_semesters'].' semesters':'Duration not set' ?></span></div><span class="gov-status <?= e($programme['status']) ?>"><?= e(ucfirst($programme['status'])) ?></span></article><?php endforeach;?><div class="gov-filter-empty" hidden><strong>No matching programmes</strong><span>Try another code, name, or school.</span></div></div><?php else:?><div class="gov-empty"><span class="gov-icon icon-programme" aria-hidden="true"></span><h2>No programmes created</h2><p>Add the first programme mapping using the form.</p></div><?php endif;?></section></div></div>
<script>(()=>{const input=document.querySelector('[data-gov-search]'),rows=[...document.querySelectorAll('[data-gov-row]')],empty=document.querySelector('.gov-filter-empty');input?.addEventListener('input',()=>{const term=input.value.trim().toLowerCase();let shown=0;rows.forEach(row=>{const visible=row.dataset.search.includes(term);row.hidden=!visible;if(visible)shown++;});if(empty)empty.hidden=shown!==0;});})();</script>
